export async function findIssuesByIds(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<readonly Issue[]> {
  if (issueIds.length === 0) return [];

  const db = getDb();
  const rows = db
    .select()
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), inArray(issues.id, [...issueIds])),
    )
    .all();

  const labelRows = db
    .select({ issueId: issueLabels.issueId, labelId: issueLabels.labelId })
    .from(issueLabels)
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        inArray(issueLabels.issueId, [...issueIds]),
      ),
    )
    .orderBy(sql`rowid`)
    .all();

  const labelsByIssue = new Map<string, LabelIdBrand[]>();
  for (const row of labelRows) {
    const list = labelsByIssue.get(row.issueId) ?? [];
    list.push(row.labelId as LabelIdBrand);
    labelsByIssue.set(row.issueId, list);
  }

  const byId = new Map(
    rows.map((row) => [row.id, toIssue(row, labelsByIssue.get(row.id) ?? [])]),
  );

  return issueIds.map((id) => {
    const issue = byId.get(id);
    if (!issue) throw new Error(`Issue ${id} not found`);
    return issue;
  });
}

