/**
 * Persisted bulk-import receipts. The upload key is unique per workspace, so
 * a second upload of the same key replays the first result and writes nothing.
 */
import { and, eq, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, issueImports, issueLabels, issues, labels } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { brandId } from "./_mappers";
import type { IssueId, IsoTimestamp, OrgId, ProjectId, UserId } from "@/types/common";
import type { IssuePriority, IssueStatus } from "@/types/issue";
import type { LabelId } from "@/types/common";

/** Colour and description used when an import creates a label that does not exist yet. */
const DEFAULT_LABEL_COLOR = "#94a3b8";

export interface StoredIssueImport {
  readonly projectId: ProjectId;
  readonly issueIds: readonly IssueId[];
}

export interface IssueImportWriteRow {
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly assigneeId: UserId | null;
  readonly dueAt: IsoTimestamp | null;
  readonly labelNames: readonly string[];
}

export interface CommittedIssueImport extends StoredIssueImport {
  readonly replayed: boolean;
}

export async function findIssueImport(
  orgId: OrgId,
  importKey: string,
): Promise<StoredIssueImport | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();

  if (!row) return null;
  return {
    projectId: brandId<ProjectId>(row.projectId),
    issueIds: parseIssueIds(row.issueIds),
  };
}

/**
 * Inserts every row, any missing labels, and the receipt in one transaction.
 * If this workspace already stored the key, the transaction writes nothing and
 * reports the original receipt (`replayed: true`).
 */
export async function commitIssueImport(input: {
  orgId: OrgId;
  projectId: ProjectId;
  authorId: UserId;
  importKey: string;
  rows: readonly IssueImportWriteRow[];
}): Promise<CommittedIssueImport> {
  try {
    return getDb().transaction((tx) => writeImport(tx, input));
  } catch (error) {
    if (!isImportKeyConflict(error)) throw error;
    const existing = await findIssueImport(input.orgId, input.importKey);
    if (!existing) throw error;
    return { ...existing, replayed: true };
  }
}

type ImportTx = Parameters<Parameters<ReturnType<typeof getDb>["transaction"]>[0]>[0];

function writeImport(
  tx: ImportTx,
  input: {
    orgId: OrgId;
    projectId: ProjectId;
    authorId: UserId;
    importKey: string;
    rows: readonly IssueImportWriteRow[];
  },
): CommittedIssueImport {
  const existing = tx
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, input.orgId),
        eq(issueImports.importKey, input.importKey),
      ),
    )
    .get();

  if (existing) {
    return {
      projectId: brandId<ProjectId>(existing.projectId),
      issueIds: parseIssueIds(existing.issueIds),
      replayed: true,
    };
  }

  const stamp = toIsoTimestamp(new Date());
  const labelIdByName = new Map<string, LabelId>();
  const existingLabels = tx
    .select()
    .from(labels)
    .where(orgPredicate(labels.orgId, input.orgId))
    .all();

  for (const label of existingLabels) {
    labelIdByName.set(label.name, brandId<LabelId>(label.id));
  }

  for (const row of input.rows) {
    for (const name of row.labelNames) {
      if (labelIdByName.has(name)) continue;
      const id = newId();
      tx.insert(labels)
        .values({
          id,
          orgId: input.orgId,
          name,
          color: DEFAULT_LABEL_COLOR,
          description: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();
      labelIdByName.set(name, brandId<LabelId>(id));
    }
  }

  const maxRow = tx
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, input.orgId),
        eq(issues.projectId, input.projectId),
      ),
    )
    .get();

  let number = (maxRow?.value ?? 0) + 1;
  const issueIds: IssueId[] = [];

  for (const row of input.rows) {
    const issueId = newId();
    tx.insert(issues)
      .values({
        id: issueId,
        orgId: input.orgId,
        projectId: input.projectId,
        number,
        title: row.title,
        description: row.description,
        status: row.status,
        priority: row.priority,
        authorId: input.authorId,
        assigneeId: row.assigneeId,
        parentId: null,
        estimate: null,
        dueAt: row.dueAt,
        startedAt: null,
        completedAt: null,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    const labelIds = labelIdsForRow(row.labelNames, labelIdByName);
    if (labelIds.length > 0) {
      tx.insert(issueLabels)
        .values(
          labelIds.map((labelId) => ({
            orgId: input.orgId,
            issueId,
            labelId,
          })),
        )
        .run();
    }

    issueIds.push(brandId<IssueId>(issueId));
    number += 1;
  }

  tx.insert(issueImports)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      importKey: input.importKey,
      issueIds: JSON.stringify(issueIds),
      createdAt: stamp,
    })
    .run();

  return {
    projectId: input.projectId,
    issueIds,
    replayed: false,
  };
}

function labelIdsForRow(
  names: readonly string[],
  labelIdByName: ReadonlyMap<string, LabelId>,
): LabelId[] {
  const ids: LabelId[] = [];
  const seen = new Set<string>();
  for (const name of names) {
    if (seen.has(name)) continue;
    seen.add(name);
    const id = labelIdByName.get(name);
    if (!id) throw new Error(`Label "${name}" was not created`);
    ids.push(id);
  }
  return ids;
}

function parseIssueIds(raw: string): readonly IssueId[] {
  try {
    const parsed: unknown = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed
      .filter((id): id is string => typeof id === "string")
      .map((id) => brandId<IssueId>(id));
  } catch {
    return [];
  }
}

function isImportKeyConflict(error: unknown): boolean {
  if (!(error instanceof Error)) return false;
  return (
    error.message.includes("issue_imports") &&
    error.message.includes("UNIQUE")
  );
}

