type ImportTx = Parameters<Parameters<ReturnType<typeof getDb>["transaction"]>[0]>[0];

function writeImport(
  tx: ImportTx,
  input: {
    orgId: OrgId;
    projectId: ProjectId;
    authorId: UserId;
    importKey: string;
    rows: readonly IssueImportWriteRow[];
  },
): CommittedIssueImport {
  const existing = tx
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, input.orgId),
        eq(issueImports.importKey, input.importKey),
      ),
    )
    .get();

  if (existing) {
    return {
      projectId: brandId<ProjectId>(existing.projectId),
      issueIds: parseIssueIds(existing.issueIds),
      replayed: true,
    };
  }

  const stamp = toIsoTimestamp(new Date());
  const labelIdByName = new Map<string, LabelId>();
  const existingLabels = tx
    .select()
    .from(labels)
    .where(orgPredicate(labels.orgId, input.orgId))
    .all();

  for (const label of existingLabels) {
    labelIdByName.set(label.name, brandId<LabelId>(label.id));
  }

  for (const row of input.rows) {
    for (const name of row.labelNames) {
      if (labelIdByName.has(name)) continue;
      const id = newId();
      tx.insert(labels)
        .values({
          id,
          orgId: input.orgId,
          name,
          color: DEFAULT_LABEL_COLOR,
          description: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();
      labelIdByName.set(name, brandId<LabelId>(id));
    }
  }

  const maxRow = tx
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, input.orgId),
        eq(issues.projectId, input.projectId),
      ),
    )
    .get();

  let number = (maxRow?.value ?? 0) + 1;
  const issueIds: IssueId[] = [];

  for (const row of input.rows) {
    const issueId = newId();
    tx.insert(issues)
      .values({
        id: issueId,
        orgId: input.orgId,
        projectId: input.projectId,
        number,
        title: row.title,
        description: row.description,
        status: row.status,
        priority: row.priority,
        authorId: input.authorId,
        assigneeId: row.assigneeId,
        parentId: null,
        estimate: null,
        dueAt: row.dueAt,
        startedAt: null,
        completedAt: null,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    const labelIds = labelIdsForRow(row.labelNames, labelIdByName);
    if (labelIds.length > 0) {
      tx.insert(issueLabels)
        .values(
          labelIds.map((labelId) => ({
            orgId: input.orgId,
            issueId,
            labelId,
          })),
        )
        .run();
    }

    issueIds.push(brandId<IssueId>(issueId));
    number += 1;
  }

  tx.insert(issueImports)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      importKey: input.importKey,
      issueIds: JSON.stringify(issueIds),
      createdAt: stamp,
    })
    .run();

  return {
    projectId: input.projectId,
    issueIds,
    replayed: false,
  };
}

function labelIdsForRow(
  names: readonly string[],
  labelIdByName: ReadonlyMap<string, LabelId>,
): LabelId[] {
  const ids: LabelId[] = [];
  const seen = new Set<string>();
  for (const name of names) {
    if (seen.has(name)) continue;
    seen.add(name);
    const id = labelIdByName.get(name);
    if (!id) throw new Error(`Label "${name}" was not created`);
    ids.push(id);
  }
  return ids;
}

