/**
 * Turns every row of one upload into an issue, in file order.
 *
 * The same gates as `createIssue` apply to the whole batch before anything is
 * written: tenant scope, `issue:create`, a live project, the plan's
 * per-project quota and the workspace's issue-creation rate allowance (one
 * unit per row). A key this workspace has already imported returns that first
 * result with `replayed: true` and writes nothing.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const existing = await importRepo.findIssueImport(input.orgId, input.importKey);
  if (existing) {
    return {
      importKey: input.importKey,
      projectId: existing.projectId,
      issues: await issueRepo.findIssuesByIds(input.orgId, existing.issueIds),
      replayed: true,
    };
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used, input.rows.length)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  setOrgPlan(input.orgId, org.plan);
  const verdict = await consumeRateLimit(
    input.orgId,
    ISSUE_CREATE_BUCKET,
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Rate limit exceeded for ${ISSUE_CREATE_BUCKET}; retry after ${verdict.resetAt}`,
    );
  }

  const membersByEmail = await memberRepo.listActiveMemberIdsByEmail(input.orgId);
  const written = await importRepo.commitIssueImport({
    orgId: input.orgId,
    projectId: input.projectId,
    authorId: actor.userId,
    importKey: input.importKey,
    rows: input.rows.map((row) => ({
      title: row.title,
      description: row.description ?? null,
      status: row.status ?? "backlog",
      priority: row.priority ?? "none",
      assigneeId: resolveAssignee(membersByEmail, row.assigneeEmail),
      dueAt: row.dueAt ?? null,
      labelNames: uniqueLabelNames(row.labels ?? []),
    })),
  });

  const issues = await issueRepo.findIssuesByIds(input.orgId, written.issueIds);
  if (written.replayed) {
    return {
      importKey: input.importKey,
      projectId: written.projectId,
      issues,
      replayed: true,
    };
  }

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: written.projectId,
    importKey: input.importKey,
    issueIds: written.issueIds,
  });

  return {
    importKey: input.importKey,
    projectId: written.projectId,
    issues,
    replayed: false,
  };
}

function resolveAssignee(
  membersByEmail: ReadonlyMap<string, UserId>,
  email: string | null | undefined,
): UserId | null {
  if (email == null || email === "") return null;
  return membersByEmail.get(email.toLowerCase()) ?? null;
}

/** First-seen order, so a name repeated inside one row is attached once. */
function uniqueLabelNames(names: readonly string[]): string[] {
  const seen = new Set<string>();
  const unique: string[] = [];
  for (const name of names) {
    if (seen.has(name)) continue;
    seen.add(name);
    unique.push(name);
  }
  return unique;
}

