import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { resetRateLimits } from "@/lib/rate-limit";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { importIssuesSchema } from "@/schemas/issue-import";
import { getDb, issueImports, labels, notifications, webhookDeliveries } from "@/server/db";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { NotFoundError } from "@/server/services/_support";
import {
  registerEventHandlers,
  unregisterEventHandlers,
} from "@/server/services/event-registry";
import * as issueService from "@/server/services/issue-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import { eq } from "drizzle-orm";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("import", "free");
  registerEventHandlers();
});

afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

function rows(partials: ReadonlyArray<Record<string, unknown>>) {
  return importIssuesSchema.parse({
    orgId: tenant.org.id,
    projectId: tenant.project.id,
    importKey: "upload-key-001",
    rows: partials,
  });
}

describe("importIssues", () => {
  it("imports rows in order and replays the key", async () => {
    resetRateLimits();
    const seenCreated: unknown[] = [];
    const seenImported: unknown[] = [];
    const offCreated = subscribe("issue.created", (payload) => {
      seenCreated.push(payload);
    });
    const offImported = subscribe("issues.imported", (payload) => {
      seenImported.push(payload);
    });

    const outsider = await userRepo.insertUser({
      email: "outsider@example.test",
      name: "Outsider",
      passwordHash: "seed",
    });
    const removed = await userRepo.insertUser({
      email: "removed@example.test",
      name: "Removed",
      passwordHash: "seed",
    });
    const removedMember = await memberRepo.insertMember(
      tenant.org.id,
      removed.id,
      "member",
      null,
    );
    await memberRepo.archiveMember(tenant.org.id, removedMember.id);

    const other = await createTenant("import-other", "free");
    await labelRepo.insertLabel({
      orgId: other.org.id,
      name: "Bug",
      color: "#ff0000",
      description: "foreign",
    });

    const input = rows([
      {
        title: "First imported",
        description: "alpha",
        status: "todo",
        priority: "high",
        assigneeEmail: "MEMBER@Import.test",
        labels: ["Bug", "Bug", "backend"],
        dueAt: "2026-12-01T00:00:00.000Z",
      },
      {
        title: "Second imported",
        assigneeEmail: outsider.email,
        labels: ["backend", "bug"],
      },
      {
        title: "Third imported",
        assigneeEmail: "removed@example.test",
        labels: [],
      },
    ]);

    const first = await issueService.importIssues(tenant.actors.member, input);

    expect(first.replayed).toBe(false);
    expect(first.projectId).toBe(tenant.project.id);
    expect(first.issues.map((issue) => issue.title)).toEqual([
      "First imported",
      "Second imported",
      "Third imported",
    ]);
    expect(first.issues.map((issue) => issue.number)).toEqual([1, 2, 3]);
    expect(first.issues.every((issue) => issue.authorId === tenant.userIds.member)).toBe(true);
    expect(first.issues.every((issue) => issue.parentId === null && issue.estimate === null)).toBe(true);
    expect(first.issues[0]).toMatchObject({
      description: "alpha",
      status: "todo",
      priority: "high",
      assigneeId: tenant.userIds.member,
      dueAt: "2026-12-01T00:00:00.000Z",
    });
    expect(first.issues[1]?.assigneeId).toBeNull();
    expect(first.issues[2]?.assigneeId).toBeNull();
    expect(first.issues[1]).toMatchObject({
      description: null,
      status: "backlog",
      priority: "none",
      dueAt: null,
    });

    const orgLabels = await labelRepo.listLabels(tenant.org.id);
    expect(orgLabels.map((label) => label.name).sort()).toEqual(["Bug", "backend", "bug"]);
    const bug = orgLabels.find((label) => label.name === "Bug");
    const backend = orgLabels.find((label) => label.name === "backend");
    const bugLower = orgLabels.find((label) => label.name === "bug");
    expect(bug).toMatchObject({ color: "#94a3b8", description: null });
    expect(first.issues[0]?.labelIds).toEqual([bug?.id, backend?.id]);
    expect(first.issues[1]?.labelIds).toEqual([backend?.id, bugLower?.id]);
    const foreign = await labelRepo.listLabels(other.org.id);
    expect(foreign).toHaveLength(1);
    expect(foreign[0]?.id).not.toBe(bug?.id);

    expect(seenCreated).toHaveLength(0);
    expect(seenImported).toHaveLength(1);
    expect(seenImported[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      projectId: tenant.project.id,
      importKey: "upload-key-001",
      issueIds: first.issues.map((issue) => issue.id),
    });

    const usage = await usageRepo.getUsage(tenant.org.id);
    const recounted = await usageRepo.recomputeUsage(tenant.org.id);
    expect(usage.issuesUsed).toBe(3);
    expect(recounted.issuesUsed).toBe(3);

    const activity = await activityRepo.listActivity({
      orgId: tenant.org.id,
      limit: 20,
      cursor: null,
    });
    const imported = activity.items.filter((event) => event.action === "issues.imported");
    expect(imported).toHaveLength(1);
    expect(imported[0]).toMatchObject({
      actorId: tenant.userIds.member,
      subjectKind: "project",
      subjectId: tenant.project.id,
      projectId: tenant.project.id,
      metadata: { count: 3, importKey: "upload-key-001" },
    });
    expect(activity.items.filter((event) => event.action === "issue.created")).toHaveLength(0);

    const hits = await searchRepo.searchDocuments({
      orgId: tenant.org.id,
      q: "First imported",
      limit: 10,
      cursor: null,
    });
    expect(hits.items.some((hit) => hit.subjectId === first.issues[0]?.id)).toBe(true);

    const notes = getDb()
      .select()
      .from(notifications)
      .where(eq(notifications.orgId, tenant.org.id))
      .all();
    expect(notes).toHaveLength(0);

    await webhookRepo.insertEndpoint(
      {
        orgId: tenant.org.id,
        url: "https://example.test/hook",
        eventTypes: ["issue.created", "issue.assigned", "issue.status_changed"],
      },
      "secret",
    );

    const replay = await issueService.importIssues(
      tenant.actors.member,
      importIssuesSchema.parse({
        ...input,
        rows: [{ title: "Completely different title" }],
      }),
    );
    expect(replay.replayed).toBe(true);
    expect(replay.issues.map((issue) => issue.id)).toEqual(first.issues.map((issue) => issue.id));
    expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id)).toBe(3);
    expect(seenImported).toHaveLength(1);

    const deliveries = getDb()
      .select()
      .from(webhookDeliveries)
      .where(eq(webhookDeliveries.orgId, tenant.org.id))
      .all();
    expect(deliveries).toHaveLength(0);

    const again = await issueService.importIssues(
      tenant.actors.admin,
      importIssuesSchema.parse({
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        importKey: "upload-key-002",
        rows: [{ title: "Fourth imported", labels: ["Bug"] }],
      }),
    );
    expect(again.replayed).toBe(false);
    expect(again.issues[0]?.number).toBe(4);
    expect(again.issues[0]?.authorId).toBe(tenant.userIds.admin);
    expect(again.issues[0]?.labelIds).toEqual([bug?.id]);
    expect((await labelRepo.listLabels(tenant.org.id)).filter((label) => label.name === "Bug")).toHaveLength(1);

    const otherImport = await issueService.importIssues(
      other.actors.member,
      importIssuesSchema.parse({
        orgId: other.org.id,
        projectId: other.project.id,
        importKey: "upload-key-001",
        rows: [{ title: "Other workspace" }],
      }),
    );
    expect(otherImport.replayed).toBe(false);
    expect(otherImport.issues[0]?.title).toBe("Other workspace");

    const created = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "After the import" }),
    );
    expect(created.number).toBe(5);

    offCreated();
    offImported();
  });

  it("refuses the batch without spending the key when the quota or rate limit is short", async () => {
    resetRateLimits();
    const quotaTenant = await createTenant("import-quota", "free");
    for (let number = 1; number <= 98; number += 1) {
      await issueRepo.insertIssue(
        issueInput(quotaTenant.org.id, quotaTenant.project.id, {
          title: `Seed ${number}`,
        }),
        quotaTenant.actors.member.userId,
        number,
      );
    }

    const key = "quota-key-01";
    await expect(
      issueService.importIssues(
        quotaTenant.actors.member,
        importIssuesSchema.parse({
          orgId: quotaTenant.org.id,
          projectId: quotaTenant.project.id,
          importKey: key,
          rows: [
            { title: "One over a" },
            { title: "One over b" },
            { title: "One over c" },
          ],
        }),
      ),
    ).rejects.toThrow(/allows no more issues/);
    expect(await issueRepo.countIssues(quotaTenant.org.id, quotaTenant.project.id)).toBe(98);
    expect(
      getDb().select().from(issueImports).where(eq(issueImports.importKey, key)).all(),
    ).toHaveLength(0);

    const accepted = await issueService.importIssues(
      quotaTenant.actors.member,
      importIssuesSchema.parse({
        orgId: quotaTenant.org.id,
        projectId: quotaTenant.project.id,
        importKey: key,
        rows: [{ title: "Fits one" }, { title: "Fits two" }],
      }),
    );
    expect(accepted.replayed).toBe(false);
    expect(accepted.issues.map((issue) => issue.number)).toEqual([99, 100]);

    await expect(
      issueService.createIssue(
        quotaTenant.actors.member,
        issueInput(quotaTenant.org.id, quotaTenant.project.id, { title: "Past the limit" }),
      ),
    ).rejects.toThrow(/allows no more issues/);

    resetRateLimits();
    const rateTenant = await createTenant("import-rate", "free");
    const tooMany = Array.from({ length: 61 }, (_, index) => ({
      title: `Rate row ${index + 1}`,
    }));
    await expect(
      issueService.importIssues(
        rateTenant.actors.member,
        importIssuesSchema.parse({
          orgId: rateTenant.org.id,
          projectId: rateTenant.project.id,
          importKey: "rate-key-0001",
          rows: tooMany,
        }),
      ),
    ).rejects.toThrow(/issue:create/);
    expect(await issueRepo.countIssues(rateTenant.org.id, rateTenant.project.id)).toBe(0);

    const limited = await issueService.importIssues(
      rateTenant.actors.member,
      importIssuesSchema.parse({
        orgId: rateTenant.org.id,
        projectId: rateTenant.project.id,
        importKey: "rate-key-0001",
        rows: [{ title: "Within the allowance" }],
      }),
    );
    expect(limited.replayed).toBe(false);
    expect(limited.issues).toHaveLength(1);
  });

  it("refuses before writing when access fails", async () => {
    resetRateLimits();
    const accessTenant = await createTenant("import-access", "free");
    const key = "access-key-1";

    await expect(
      issueService.importIssues(
        accessTenant.actors.viewer,
        importIssuesSchema.parse({
          orgId: accessTenant.org.id,
          projectId: accessTenant.project.id,
          importKey: key,
          rows: [{ title: "Viewer import" }],
        }),
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      issueService.importIssues(
        accessTenant.actors.member,
        importIssuesSchema.parse({
          orgId: tenant.org.id,
          projectId: accessTenant.project.id,
          importKey: key,
          rows: [{ title: "Wrong org" }],
        }),
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      issueService.importIssues(
        accessTenant.actors.member,
        importIssuesSchema.parse({
          orgId: accessTenant.org.id,
          projectId: tenant.project.id,
          importKey: key,
          rows: [{ title: "Foreign project" }],
        }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await projectRepo.archiveProject(accessTenant.org.id, accessTenant.project.id);
    await expect(
      issueService.importIssues(
        accessTenant.actors.member,
        importIssuesSchema.parse({
          orgId: accessTenant.org.id,
          projectId: accessTenant.project.id,
          importKey: key,
          rows: [{ title: "Archived project" }],
        }),
      ),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    expect(await issueRepo.countIssues(accessTenant.org.id, accessTenant.project.id)).toBe(0);
    expect(
      getDb().select().from(labels).where(eq(labels.orgId, accessTenant.org.id)).all(),
    ).toHaveLength(0);
    await projectRepo.restoreProject(accessTenant.org.id, accessTenant.project.id);
    const after = await issueService.importIssues(
      accessTenant.actors.member,
      importIssuesSchema.parse({
        orgId: accessTenant.org.id,
        projectId: accessTenant.project.id,
        importKey: key,
        rows: [{ title: "After restore" }],
      }),
    );
    expect(after.replayed).toBe(false);
    expect(after.issues[0]?.title).toBe("After restore");
  });
});

